class _LeaseManager:
    """Cross-process registry of snapshots currently in use.

    A process that opens a read-only store or holds a cursor over some
    snapshot owns exactly one lease sidecar -- ``wal.lease.<pid>.<rand>``,
    all of the single ``wal.lease.*`` kind -- listing every snapshot that
    process has in use, one fixed-width
    ``wal.l<seq>.<sid>.<heartbeat>\\n`` record each. The file is rewritten
    atomically (temp file, fsync, rename, directory fsync) on every change
    and every heartbeat, so another process never observes a half-written
    record: what it reads is one complete lease image or the previous one.

    Because each process writes only its own file, registering, refreshing
    and removing a lease never races another process's lease. An orderly
    ``close()`` deletes the sidecar; a process killed without closing simply
    stops heartbeating, and the writer then ignores every record whose
    timestamp is older than the TTL and sweeps the stale file. The writer
    reads *all* lease sidecars before reclaiming a copy, so a snapshot a
    cursor or a read-only store in any process is serving is never removed.

    A lease is a protection, never a requirement: writes are best-effort, so
    a read-only directory simply has no sidecar and reading is unaffected,
    while the in-process pins still apply.
    """

    def __init__(self, directory: str):
        self._dir = directory
        # A unique name per process instance. The random suffix keeps two
        # incarnations of one pid (pid reuse, or two processes in copied
        # directories) from ever sharing a sidecar.
        self._name = (f"{_LEASE_PREFIX}{os.getpid()}."
                      f"{uuid.uuid4().hex}")
        self._path = os.path.join(directory, self._name)
        # Snapshot keys this process currently leases.
        self._keys: set[tuple[int, bytes]] = set()
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._thread = None
        self._disabled = False

    # -- record format -----------------------------------------------------

    @staticmethod
    def _record(seq: int, sid: bytes, now: float) -> bytes:
        ts = f"{now:.6f}".encode("ascii")
        if len(ts) > _LEASE_TS_LEN:
            ts = ts[-_LEASE_TS_LEN:]
        return (f"{_LEASE_REC_PREFIX}{seq:0{_LEASE_SEQ_MAX}d}."
                f"{sid.hex()}.").encode("ascii") + ts.rjust(
            _LEASE_TS_LEN, b"0") + b"\n"

    def _image(self, now: float) -> bytes:
        return b"".join(self._record(seq, sid, now)
                        for seq, sid in sorted(self._keys))

    def _publish(self, now: float | None = None) -> None:
        """Atomically write this process's current lease image."""
        if self._disabled:
            return
        if now is None:
            now = time.time()
        data = self._image(now)
        tmp = self._path + ".tmp"
        try:
            with open(tmp, "wb") as f:
                f.write(data)
                os.fsync(f.fileno())
            os.replace(tmp, self._path)
            _fsync_dir(self._dir)
        except OSError:
            # A read-only directory or a refused write must not break the
            # reader; the lease simply stays unregistered.
            self._disabled = True
            try:
                os.unlink(tmp)
            except OSError:
                pass

    # -- lease lifecycle ---------------------------------------------------

    def acquire(self, seq: int, sid: bytes) -> None:
        """Register a lease for ``(seq, sid)``; idempotent per process."""
        with self._lock:
            if sid is None or key_contains(self._keys, seq, sid):
                return
            self._keys.add((seq, sid))
            self._publish()
            self._start_locked()

    def release(self, seq: int, sid: bytes) -> None:
        """Drop one snapshot's lease; best-effort and idempotent."""
        with self._lock:
            before = len(self._keys)
            self._keys = {k for k in self._keys
                          if not (k[0] == seq and k[1] == sid)}
            if len(self._keys) == before:
                return
            if self._keys:
                self._publish()
            else:
                self._remove_locked()
            if not self._keys:
                self._stop_locked()

    def close(self) -> None:
        """Retire every lease this process held."""
        with self._lock:
            if self._keys or self._thread is not None:
                self._remove_locked()
            self._keys.clear()
            self._stop_locked()

    def _remove_locked(self) -> None:
        if self._disabled:
            return
        try:
            os.unlink(self._path)
            _fsync_dir(self._dir)
        except FileNotFoundError:
            pass
        except OSError:
            # Left behind only if unwritable: it will expire by heartbeat.
            pass

    # -- heartbeat ---------------------------------------------------------

    def _start_locked(self) -> None:
        if self._thread is not None or self._disabled:
            return
        self._stop.clear()
        self._thread = threading.Thread(
            target=self._run, name="wal-lease-heartbeat", daemon=True)
        self._thread.start()

    def _stop_locked(self) -> None:
        if self._thread is None:
            return
        self._stop.set()
        thread = self._thread
        self._thread = None
        if thread is not threading.current_thread():
            thread.join(timeout=_LEASE_HEARTBEAT * 4)

    def _run(self) -> None:
        while not self._stop.wait(_LEASE_HEARTBEAT):
            with self._lock:
                if self._keys:
                    self._publish()

    # -- writer-side scan --------------------------------------------------

    @staticmethod
    def _parse_record(rec: bytes, now: float):
