        except UnicodeDecodeError:
            return None
        if not text.startswith(_LEASE_REC_PREFIX):
            return None
        body = text[len(_LEASE_REC_PREFIX):]
        first = body.index(".")
        second = body.index(".", first + 1)
        try:
            seq = int(body[:first])
            sid = bytes.fromhex(body[first + 1:second])
            ts = float(body[second + 1:].rstrip("\n"))
        except ValueError:
            return None
        if len(sid) != 32 or seq < 0:
            return None
        if now - ts > _LEASE_TTL:
            return None
        return seq, sid

    def _iter_lease_files(self):
        """Yield ``(name, raw)`` for each well-named lease sidecar.

        Only names of the exact ``wal.lease.<pid>.<hex>`` shape are opened;
        anything else in the directory is ignored, never parsed or removed.
        """
        try:
            names = os.listdir(self._dir)
        except OSError:
            return
        for name in names:
            if not self._is_lease_name(name):
                continue
            try:
                with open(os.path.join(self._dir, name), "rb") as f:
                    yield name, f.read()
            except OSError:
                continue

    @staticmethod
    def _is_lease_name(name: str) -> bool:
        if not name.startswith(_LEASE_PREFIX):
            return False
        tail = name[len(_LEASE_PREFIX):]
        pid, sep, rand = tail.partition(".")
        if not sep or not pid.isdigit() or not rand:
            return False
        # The random suffix is 32 hex characters (uuid4.hex).
        return len(rand) == 32 and all(c in "0123456789abcdef" for c in rand)

    def live_keys(self, now: float | None = None) -> set:
        """The ``(seq, sid)`` pairs with a fresh lease in any process.

        Every fresh record in every well-named lease sidecar names an in-use
        snapshot; stale heartbeats (a killed process) and malformed records
        are ignored. Reading never mutates the registry.
        """
        if now is None:
            now = time.time()
        live: set[tuple[int, bytes]] = set()
        for _name, raw in self._iter_lease_files():
            for off in range(0, len(raw), _LEASE_REC_LEN):
                rec = raw[off:off + _LEASE_REC_LEN]
                key = self._parse_record(rec, now)
                if key is not None:
                    live.add(key)
        return live

    def prune(self, now: float | None = None) -> None:
        """Remove lease sidecars that name no live user.

        A sidecar whose every record is stale or malformed belongs to a
        process that closed by being killed (its heartbeat stopped) and is
        swept; a sidecar with at least one fresh record is left byte-for-byte
        untouched. Each unlink is independent, so a kill mid-sweep simply
        finishes on the next reclaim. This process's own sidecar is never
        pruned while it holds keys.
        """
        if now is None:
            now = time.time()
        for name, raw in list(self._iter_lease_files()):
            if name == self._name:
                continue
            fresh = False
            for off in range(0, len(raw), _LEASE_REC_LEN):
                if self._parse_record(raw[off:off + _LEASE_REC_LEN],
                                      now) is not None:
                    fresh = True
                    break
            if fresh:
                continue
            try:
                os.unlink(os.path.join(self._dir, name))
            except FileNotFoundError:
                pass
            except OSError:
                continue
        _fsync_dir(self._dir)


def key_contains(keys, seq: int, sid: bytes) -> bool:
    """Membership test that compares an identity without hashing it twice."""
    for s, i in keys:
        if s == seq and i == sid:
            return True
    return False

